<?php
declare(strict_types=1);
final class WorkPlanningService {
    public static function overview(int $workspace):array{
        WorkService::workspace($workspace);$projects=WorkService::projects($workspace);$self=WorkService::self($workspace);$where="p.workspace_id=? AND p.status<>'archived' AND i.deleted_at IS NULL AND i.archived_at IS NULL AND i.intake_status='accepted'";
        $stats=Db::one("SELECT COUNT(*) total,COALESCE(SUM(s.state_group='completed'),0) completed,COALESCE(SUM(s.state_group NOT IN ('completed','cancelled') AND i.due_date<?),0) overdue,COALESCE(SUM(s.state_group='started'),0) active FROM work_issues i JOIN work_projects p ON p.id=i.project_id JOIN work_states s ON s.id=i.state_id WHERE $where",[date('Y-m-d'),$workspace]);
        $mine=Db::all("SELECT i.*,p.identifier,p.name project_name,s.name state_name,s.state_group,s.color state_color FROM work_issues i JOIN work_projects p ON p.id=i.project_id JOIN work_states s ON s.id=i.state_id JOIN work_issue_assignees a ON a.issue_id=i.id AND a.person_id=? WHERE $where ORDER BY s.state_group IN ('completed','cancelled'),i.due_date IS NULL,i.due_date,i.id DESC LIMIT 50",[$self,$workspace]);
        $intake=Db::all("SELECT i.*,p.identifier,p.name project_name FROM work_issues i JOIN work_projects p ON p.id=i.project_id WHERE p.workspace_id=? AND p.status<>'archived' AND i.intake_status='pending' AND i.deleted_at IS NULL AND i.archived_at IS NULL ORDER BY i.id DESC LIMIT 100",[$workspace]);
        $activity=Db::all('SELECT a.*,p.name project_name,u.name actor_name FROM work_activity a JOIN work_projects p ON p.id=a.project_id JOIN work_people u ON u.id=a.actor_id WHERE p.workspace_id=? ORDER BY a.id DESC LIMIT 30',[$workspace]);
        $favorites=[];foreach(Db::all('SELECT * FROM work_favorites WHERE workspace_id=?',[$workspace]) as $favorite){if($favorite['entity']==='project'){$row=Db::one('SELECT id,name title,identifier FROM work_projects WHERE id=? AND workspace_id=?',[$favorite['entity_id'],$workspace]);$route=$row?'/work/project/'.$row['id']:'';}else{$row=Db::one('SELECT i.id,i.title,p.identifier,i.sequence FROM work_issues i JOIN work_projects p ON p.id=i.project_id WHERE i.id=? AND p.workspace_id=? AND i.deleted_at IS NULL',[$favorite['entity_id'],$workspace]);$route=$row?'/work/issue/'.$row['id']:'';}if($row)$favorites[]=[...$row,'entity'=>$favorite['entity'],'route'=>$route];}
        $timer=Db::one('SELECT t.*,i.title,p.identifier,i.sequence FROM work_timers t JOIN work_issues i ON i.id=t.issue_id JOIN work_projects p ON p.id=i.project_id WHERE t.workspace_id=?',[$workspace]);return compact('projects','stats','mine','intake','activity','favorites','timer');
    }
    public static function analytics(int $project):array{
        WorkService::project($project);$where="i.project_id=? AND i.deleted_at IS NULL AND i.archived_at IS NULL AND i.intake_status='accepted'";$stats=Db::one("SELECT COUNT(*) total,COALESCE(SUM(s.state_group='completed'),0) completed,COALESCE(SUM(s.state_group='started'),0) active,COALESCE(SUM(s.state_group NOT IN ('completed','cancelled') AND i.due_date<?),0) overdue,COALESCE(SUM(i.estimate),0) points FROM work_issues i JOIN work_states s ON s.id=i.state_id WHERE $where",[date('Y-m-d'),$project]);
        $byState=Db::all("SELECT s.name,s.color,s.state_group,COUNT(i.id) total FROM work_states s LEFT JOIN work_issues i ON i.state_id=s.id AND i.deleted_at IS NULL AND i.archived_at IS NULL AND i.intake_status='accepted' WHERE s.project_id=? GROUP BY s.id ORDER BY s.position,s.id",[$project]);
        $byPriority=Db::all("SELECT i.priority,COUNT(*) total FROM work_issues i WHERE $where GROUP BY i.priority ORDER BY i.priority",[$project]);
        $byPerson=Db::all("SELECT u.id,u.name,COUNT(i.id) total,COALESCE(SUM(s.state_group='completed'),0) completed FROM work_people u JOIN work_issue_assignees a ON a.person_id=u.id JOIN work_issues i ON i.id=a.issue_id JOIN work_states s ON s.id=i.state_id WHERE $where GROUP BY u.id ORDER BY total DESC,u.name",[$project]);
        $minutes=(int)Db::one('SELECT COALESCE(SUM(t.minutes),0) total FROM work_time_entries t JOIN work_issues i ON i.id=t.issue_id WHERE i.project_id=?',[$project])['total'];$history=Db::all('SELECT * FROM work_snapshots WHERE project_id=? AND cycle_id=0 ORDER BY day',[$project]);$events=Db::all("SELECT day,SUM(event='issue.created') created,SUM(event='issue.completed') completed FROM work_activity WHERE project_id=? GROUP BY day ORDER BY day",[$project]);return compact('stats','byState','byPriority','byPerson','minutes','history','events');
    }
    public static function saveView(int $project,array $data,?int $id=null):int{
        $name=WorkService::text($data['name']??'',160,true);$layout=$data['layout']??'list';if(!is_string($layout)||!isset(WorkService::LAYOUTS[$layout]))throw new InvalidArgumentException('Choose a valid saved-view layout.');$input=$data['filters']??[];if(!is_array($input))throw new InvalidArgumentException('Choose valid view filters.');$filters=WorkIssueService::filters($project,$input);if($id){WorkService::scoped('work_views',$project,$id);Db::run('UPDATE work_views SET name=?,layout=?,filters=? WHERE id=?',[$name,$layout,json_encode($filters,JSON_THROW_ON_ERROR),$id]);return $id;}return Db::run('INSERT INTO work_views(project_id,name,layout,filters) VALUES (?,?,?,?)',[$project,$name,$layout,json_encode($filters,JSON_THROW_ON_ERROR)]);
    }
    public static function completeCycle(int $project,int $cycle,?int $moveTo):void{
        $source=WorkService::scoped('work_cycles',$project,$cycle);if($source['status']==='completed')throw new InvalidArgumentException('This cycle is already completed.');if($moveTo){$target=WorkService::scoped('work_cycles',$project,$moveTo);if($moveTo===$cycle||$target['status']==='completed')throw new InvalidArgumentException('Choose a different incomplete target cycle.');}
        Db::tx(function()use($project,$cycle,$moveTo,$source){if($moveTo){$issues=Db::all("SELECT i.id FROM work_issues i JOIN work_states s ON s.id=i.state_id WHERE i.project_id=? AND i.cycle_id=? AND i.deleted_at IS NULL AND i.archived_at IS NULL AND s.state_group NOT IN ('completed','cancelled')",[$project,$cycle]);foreach($issues as $issue){Db::run('UPDATE work_issues SET cycle_id=?,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=?',[$moveTo,$issue['id']]);WorkService::log($project,(int)$issue['id'],'issue.cycle_carried',$source['name']);}}Db::run("UPDATE work_cycles SET status='completed' WHERE id=?",[$cycle]);WorkService::snapshot($project);WorkService::log($project,null,'cycle.completed',$source['name']);});
    }
    public static function rollbackPage(int $project,int $id,int $current,int $target):void{
        $page=WorkService::scoped('work_pages',$project,$id);if((int)$page['version']!==$current)throw new InvalidArgumentException('This page changed. Reload before rollback.');$source=Db::one('SELECT * FROM work_page_versions WHERE page_id=? AND version=?',[$id,$target]);if(!$source)throw new InvalidArgumentException('Page version not found.');WorkService::savePage($project,['title'=>$source['title'],'body'=>$source['body'],'pinned'=>(string)$page['pinned'],'version'=>$current],$id);
    }
    public static function pageToIssue(int $project,int $page,array $data):int{
        $source=WorkService::scoped('work_pages',$project,$page);if($source['deleted_at']!==null)throw new InvalidArgumentException('Restore this page before converting it.');$id=WorkIssueService::save($project,['title'=>$data['title']??$source['title'],'description'=>$data['description']??$source['body']]);Db::run('INSERT INTO work_page_issues(page_id,issue_id) VALUES (?,?)',[$page,$id]);return $id;
    }
    public static function removeState(int $project,int $state,int $replacement):void{
        WorkService::scoped('work_states',$project,$state);WorkService::scoped('work_states',$project,$replacement);if($state===$replacement)throw new InvalidArgumentException('Choose a different replacement state.');Db::tx(function()use($project,$state,$replacement){Db::run('UPDATE work_issues SET state_id=?,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE project_id=? AND state_id=?',[$replacement,$project,$state]);Db::run('DELETE FROM work_states WHERE id=?',[$state]);WorkService::log($project,null,'workflow.removed',(string)$state);WorkService::snapshot($project);});
    }
    public static function export(int $project):array{
        $p=WorkService::project($project);$tables=[];foreach(['work_states','work_labels','work_cycles','work_modules','work_releases','work_issues','work_pages','work_views','work_activity','work_snapshots'] as $table)$tables[$table]=Db::all('SELECT * FROM '.$table.' WHERE project_id=?',[$project]);foreach(['work_issue_assignees','work_issue_labels','work_comments','work_time_entries','work_attachments'] as $table)$tables[$table]=Db::all('SELECT x.* FROM '.$table.' x JOIN work_issues i ON i.id=x.issue_id WHERE i.project_id=?',[$project]);$tables['work_relations']=Db::all('SELECT * FROM work_relations WHERE project_id=?',[$project]);$tables['work_page_versions']=Db::all('SELECT v.* FROM work_page_versions v JOIN work_pages p ON p.id=v.page_id WHERE p.project_id=?',[$project]);$tables['work_people']=WorkService::people((int)$p['workspace_id']);return ['format'=>'lifeos-work-v1','exported_at'=>gmdate('c'),'project'=>$p,'data'=>$tables];
    }
    public static function dueIssues(int $days=7):array{return Db::all("SELECT i.id,i.title,i.due_date,p.identifier,i.sequence FROM work_issues i JOIN work_projects p ON p.id=i.project_id JOIN work_states s ON s.id=i.state_id WHERE p.status<>'archived' AND i.deleted_at IS NULL AND i.archived_at IS NULL AND i.intake_status='accepted' AND i.due_date<=? AND s.state_group NOT IN ('completed','cancelled') ORDER BY i.due_date LIMIT 20",[date('Y-m-d',strtotime('+'.$days.' days'))]);}
}
